// src/Component/ActivityLog.js

import React, { useEffect, useState } from "react";
import axios from "axios";
import "./ActivityLog.css";

const ActivityLog = () => {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchLogs = async () => {
      try {
        const token = localStorage.getItem("token");
        const res = await axios.get("http://127.0.0.1:8000/api/activity-logs/", {
          headers: { Authorization: `Bearer ${token}` },
        });
        setLogs(res.data);
      } catch (err) {
        console.error(err);
        setError("Failed to load activity logs");
      } finally {
        setLoading(false);
      }
    };

    fetchLogs();
  }, []);

  if (loading) return <p>Loading activity logs...</p>;
  if (error) return <p>{error}</p>;

  return (
    <div className="activity-log-container">
      <h2>All User Activity Timeline</h2>
      {logs.length === 0 ? (
        <p>No activity logs found.</p>
      ) : (
        <div className="activity-log-list">
          {logs.map((log, index) => (
            <div className="activity-log-item" key={index}>
              <div className="log-header">
                <span className="log-user">{log.username}</span>
                <span className={`log-action log-${log.action}`}>
                  {log.action.toUpperCase()}
                </span>
              </div>
              <div className="log-body">
                <p><strong>Model:</strong> {log.model}</p>
                <p><strong>Object ID:</strong> {log.object_id || "-"}</p>
                {log.details && Object.keys(log.details).length > 0 && (
                  <p><strong>Details:</strong> {JSON.stringify(log.details)}</p>
                )}
                <p className="log-timestamp">{new Date(log.timestamp).toLocaleString()}</p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default ActivityLog;
